CREATE TABLE files (id uuid PRIMARY KEY,storage_key varchar(255) NOT NULL UNIQUE, original_name varchar(255) NOT NULL,mime_type varchar(100) NOT NULL,size_bytes bigint NOT NULL CHECK(size_bytes>0 AND size_bytes<=10485760),checksum varchar(64) NOT NULL, visibility varchar(20) NOT NULL DEFAULT 'private' CHECK(visibility='private'),created_at timestamptz NOT NULL);
CREATE TABLE skills (id uuid PRIMARY KEY,created_at timestamptz NOT NULL,updated_at timestamptz NOT NULL,display_order integer NOT NULL DEFAULT 0 CHECK(display_order>=0),slug text NOT NULL UNIQUE,category text NOT NULL,published boolean NOT NULL DEFAULT false);
CREATE TABLE projects (id uuid PRIMARY KEY,created_at timestamptz NOT NULL,updated_at timestamptz NOT NULL,display_order integer NOT NULL DEFAULT 0 CHECK(display_order>=0),slug text NOT NULL UNIQUE,category text NOT NULL,status text NOT NULL,github_url text,demo_url text,featured boolean NOT NULL DEFAULT false,published boolean NOT NULL DEFAULT false,started_at date,completed_at date);
CREATE TABLE certificates (id uuid PRIMARY KEY,created_at timestamptz NOT NULL,updated_at timestamptz NOT NULL,display_order integer NOT NULL DEFAULT 0 CHECK(display_order>=0),slug text NOT NULL UNIQUE,issuer text NOT NULL,category text NOT NULL,issued_at date,expires_at date,hours integer,credential_id text,verification_url text,file_id uuid REFERENCES files(id) ON DELETE RESTRICT,published boolean NOT NULL DEFAULT false);
CREATE TABLE experiences (id uuid PRIMARY KEY,created_at timestamptz NOT NULL,updated_at timestamptz NOT NULL,display_order integer NOT NULL DEFAULT 0 CHECK(display_order>=0),organization text NOT NULL,type text NOT NULL,started_at date,ended_at date,current boolean NOT NULL DEFAULT false,published boolean NOT NULL DEFAULT false);
CREATE TABLE resumes (id uuid PRIMARY KEY,created_at timestamptz NOT NULL,updated_at timestamptz NOT NULL,display_order integer NOT NULL DEFAULT 0 CHECK(display_order>=0),title text NOT NULL,locale text NOT NULL,target_profile text,description text,file_id uuid REFERENCES files(id) ON DELETE RESTRICT,is_primary boolean NOT NULL DEFAULT false,published boolean NOT NULL DEFAULT false);
CREATE TABLE courses (id uuid PRIMARY KEY,created_at timestamptz NOT NULL,updated_at timestamptz NOT NULL,display_order integer NOT NULL DEFAULT 0 CHECK(display_order>=0),name text NOT NULL,provider text NOT NULL,category text,source_url text,status text NOT NULL,progress integer CHECK(progress BETWEEN 0 AND 100),started_at date,completed_at date,notes text,certificate_id uuid REFERENCES certificates(id) ON DELETE SET NULL);
CREATE TABLE job_applications (id uuid PRIMARY KEY,created_at timestamptz NOT NULL,updated_at timestamptz NOT NULL,display_order integer NOT NULL DEFAULT 0 CHECK(display_order>=0),company text NOT NULL,position text NOT NULL,job_url text,work_mode text,salary_min numeric(14,2) CHECK(salary_min>=0),salary_max numeric(14,2) CHECK(salary_max>=0),currency text,applied_at date,status text NOT NULL,source text,resume_id uuid REFERENCES resumes(id) ON DELETE SET NULL,notes text,next_action text,follow_up_at date);
CREATE TABLE professional_profiles (id uuid PRIMARY KEY,created_at timestamptz NOT NULL,updated_at timestamptz NOT NULL,display_order integer NOT NULL DEFAULT 0 CHECK(display_order>=0),slug text NOT NULL UNIQUE,enabled boolean NOT NULL DEFAULT false,default_resume_id uuid REFERENCES resumes(id) ON DELETE SET NULL);
CREATE TABLE skill_translations (skill_id uuid NOT NULL REFERENCES skills(id) ON DELETE CASCADE,locale varchar(5) NOT NULL CHECK(locale IN ('pt-BR','en')),name text,description text,PRIMARY KEY(skill_id,locale));
CREATE INDEX skills_ordering ON skills(display_order,created_at DESC);
CREATE TABLE project_translations (project_id uuid NOT NULL REFERENCES projects(id) ON DELETE CASCADE,locale varchar(5) NOT NULL CHECK(locale IN ('pt-BR','en')),title text,summary text,description text,problem text,solution text,contribution text,architecture text,challenges text,learnings text,results text,PRIMARY KEY(project_id,locale));
CREATE TABLE project_skills (project_id uuid NOT NULL REFERENCES projects(id) ON DELETE CASCADE,skill_id uuid NOT NULL REFERENCES skills(id) ON DELETE RESTRICT,PRIMARY KEY(project_id,skill_id));
CREATE TABLE project_media(project_id uuid NOT NULL REFERENCES projects(id) ON DELETE CASCADE,file_id uuid NOT NULL REFERENCES files(id) ON DELETE RESTRICT,PRIMARY KEY(project_id,file_id));
CREATE INDEX projects_ordering ON projects(display_order,created_at DESC);
CREATE TABLE certificate_translations (certificate_id uuid NOT NULL REFERENCES certificates(id) ON DELETE CASCADE,locale varchar(5) NOT NULL CHECK(locale IN ('pt-BR','en')),title text,description text,PRIMARY KEY(certificate_id,locale));
CREATE TABLE certificate_skills (certificate_id uuid NOT NULL REFERENCES certificates(id) ON DELETE CASCADE,skill_id uuid NOT NULL REFERENCES skills(id) ON DELETE RESTRICT,PRIMARY KEY(certificate_id,skill_id));
CREATE INDEX certificates_ordering ON certificates(display_order,created_at DESC);
CREATE TABLE experience_translations (experience_id uuid NOT NULL REFERENCES experiences(id) ON DELETE CASCADE,locale varchar(5) NOT NULL CHECK(locale IN ('pt-BR','en')),role text,description text,responsibilities text,results text,PRIMARY KEY(experience_id,locale));
CREATE TABLE experience_skills (experience_id uuid NOT NULL REFERENCES experiences(id) ON DELETE CASCADE,skill_id uuid NOT NULL REFERENCES skills(id) ON DELETE RESTRICT,PRIMARY KEY(experience_id,skill_id));
CREATE INDEX experiences_ordering ON experiences(display_order,created_at DESC);
CREATE INDEX resumes_ordering ON resumes(display_order,created_at DESC);
CREATE TABLE course_skills (course_id uuid NOT NULL REFERENCES courses(id) ON DELETE CASCADE,skill_id uuid NOT NULL REFERENCES skills(id) ON DELETE RESTRICT,PRIMARY KEY(course_id,skill_id));
CREATE INDEX courses_ordering ON courses(display_order,created_at DESC);
CREATE INDEX job_applications_ordering ON job_applications(display_order,created_at DESC);
CREATE TABLE professional_profile_translations (professional_profile_id uuid NOT NULL REFERENCES professional_profiles(id) ON DELETE CASCADE,locale varchar(5) NOT NULL CHECK(locale IN ('pt-BR','en')),title text,summary text,PRIMARY KEY(professional_profile_id,locale));
CREATE TABLE professional_profile_skills (professional_profile_id uuid NOT NULL REFERENCES professional_profiles(id) ON DELETE CASCADE,skill_id uuid NOT NULL REFERENCES skills(id) ON DELETE RESTRICT,PRIMARY KEY(professional_profile_id,skill_id));
CREATE TABLE profile_projects(profile_id uuid NOT NULL REFERENCES professional_profiles(id) ON DELETE CASCADE,project_id uuid NOT NULL REFERENCES projects(id) ON DELETE RESTRICT,PRIMARY KEY(profile_id,project_id));
CREATE INDEX professional_profiles_ordering ON professional_profiles(display_order,created_at DESC);
CREATE UNIQUE INDEX one_primary_resume_per_locale ON resumes(locale) WHERE is_primary;
CREATE INDEX projects_public_category ON projects(published,category);
CREATE INDEX certificates_public_issuer ON certificates(published,issuer);
CREATE INDEX applications_status_followup ON job_applications(status,follow_up_at);
CREATE TABLE application_events(id uuid PRIMARY KEY,application_id uuid NOT NULL REFERENCES job_applications(id) ON DELETE CASCADE,previous_status text,new_status text NOT NULL,notes text,occurred_at timestamptz NOT NULL);
CREATE TABLE site_settings(key varchar(100) PRIMARY KEY,value text NOT NULL,updated_at timestamptz NOT NULL);
CREATE TABLE analytics_daily(day date NOT NULL,path varchar(255) NOT NULL,event varchar(30) NOT NULL,count bigint NOT NULL DEFAULT 0 CHECK(count>=0),PRIMARY KEY(day,path,event));
